import {
  createClient,
} from "@supabase/supabase-js";

const SUPABASE_URL =
  "https://tzozajnwznxqgxnjikoy.supabase.co";

const SUPABASE_PUBLISHABLE_KEY =
  "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1";

export function createAuthenticatedSupabase(
  accessToken: string
) {
  return createClient(
    SUPABASE_URL,
    SUPABASE_PUBLISHABLE_KEY,
    {
      global: {
        headers: {
          Authorization:
            `Bearer ${accessToken}`,
        },
      },

      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    }
  );
}

export function getBearerToken(
  request: Request
) {
  const authorization =
    request.headers.get(
      "authorization"
    ) ?? "";

  if (
    !authorization.startsWith(
      "Bearer "
    )
  ) {
    return "";
  }

  return authorization
    .slice(
      "Bearer ".length
    )
    .trim();
}

import { createClient } from "@supabase/supabase-js";
import { runUserEvolutionAnalysis } from "../../../../../lib/persona/evolution-runner";
import type { ChatMessage } from "../../../../../lib/user-profile";

const SUPABASE_URL = "https://tzozajnwznxqgxnjikoy.supabase.co";
const SUPABASE_PUBLISHABLE_KEY =
  "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1";

function createAuthenticatedSupabase(accessToken: string) {
  return createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
}

function sanitizeHistory(value: unknown): ChatMessage[] {
  return Array.isArray(value)
    ? value
        .filter(
          (item: any) =>
            item &&
            (item.role === "user" || item.role === "misaki") &&
            typeof item.text === "string" &&
            item.text.trim()
        )
        .map((item: any) => ({
          role: item.role,
          text: item.text.trim().slice(0, 2000),
        }))
        .slice(-60)
    : [];
}

function sanitizeMemory(value: unknown): string[] {
  return Array.isArray(value)
    ? value
        .filter(
          (item: unknown): item is string =>
            typeof item === "string" && item.trim().length > 0
        )
        .map((item) => item.trim().slice(0, 500))
        .slice(-30)
    : [];
}

export async function POST(request: Request) {
  try {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return Response.json(
        { error: "Gemini API key is missing." },
        { status: 500 }
      );
    }

    const authorization = request.headers.get("authorization") ?? "";
    if (!authorization.startsWith("Bearer ")) {
      return Response.json(
        { error: "Authentication required." },
        { status: 401 }
      );
    }

    const accessToken = authorization.slice("Bearer ".length).trim();
    const supabase = createAuthenticatedSupabase(accessToken);
    const { data: userData, error: userError } =
      await supabase.auth.getUser(accessToken);

    if (userError || !userData.user) {
      return Response.json(
        { error: "Authentication required." },
        { status: 401 }
      );
    }

    const body = await request.json();
    let safeHistory = sanitizeHistory(body?.history);
    let safeMemory = sanitizeMemory(body?.memory);
    let historySource: "browser" | "server" = "browser";

    const browserUserMessageCount = safeHistory.filter(
      (item) => item.role === "user"
    ).length;

    if (userData.user.is_anonymous !== true || browserUserMessageCount === 0) {
      const { data: storedState, error: storedError } = await supabase
        .from("misaki_user_conversation_state")
        .select("history,memory")
        .eq("user_id", userData.user.id)
        .maybeSingle();

      if (storedError) {
        console.error("EVOLUTION STORED HISTORY LOAD ERROR:", storedError);
        if (userData.user.is_anonymous !== true) return Response.json({ error: "Canonical context unavailable." }, { status: 500 });
      } else if (!storedState && userData.user.is_anonymous !== true) {
        safeHistory = []; safeMemory = []; historySource = "server";
      } else if (storedState) {
        const storedHistory = sanitizeHistory(storedState.history);
        const storedMemory = sanitizeMemory(storedState.memory);

        if (userData.user.is_anonymous !== true || storedHistory.some((item) => item.role === "user")) {
          safeHistory = storedHistory;
          safeMemory = storedMemory;
          historySource = "server";
        }
      }
    }

    const userMessageCount = safeHistory.filter(
      (item) => item.role === "user"
    ).length;

    if (safeHistory.length === 0 || userMessageCount === 0) {
      return Response.json({
        analyzed: false,
        skipped: true,
        reason: "insufficient_history",
        saved: 0,
        historySource,
        historyCount: safeHistory.length,
        userMessageCount,
        memoryCount: safeMemory.length,
        autoApplied: false,
      });
    }

    const result = await runUserEvolutionAnalysis(
      supabase,
      userData.user.id,
      apiKey,
      safeHistory,
      safeMemory,
      { force: true }
    );

    return Response.json({
      ...result,
      historySource,
      historyCount: safeHistory.length,
      userMessageCount,
      memoryCount: safeMemory.length,
      autoApplied: false,
    });
  } catch (error) {
    console.error("EVOLUTION ANALYZE ROUTE ERROR:", error);
    return Response.json(
      {
        analyzed: false,
        error: "Evolution analysis failed.",
      },
      { status: 500 }
    );
  }
}

import {
  createAuthenticatedSupabase,
  getBearerToken,
} from "../_auth";

export async function GET(
  request: Request
) {
  try {
    const accessToken =
      getBearerToken(
        request
      );

    if (!accessToken) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const supabase =
      createAuthenticatedSupabase(
        accessToken
      );

    const {
      data: userData,
      error: userError,
    } =
      await supabase.auth.getUser(
        accessToken
      );

    if (
      userError ||
      !userData.user
    ) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const url =
      new URL(
        request.url
      );

    const statusParam =
      url.searchParams.get(
        "status"
      );

    const status =
      statusParam ===
        "approved" ||
      statusParam ===
        "rejected" ||
      statusParam ===
        "pending"
        ? statusParam
        : "pending";

    const {
      data,
      error,
    } =
      await supabase
        .from(
          "misaki_evolution_candidates"
        )
        .select(
          [
            "id",
            "trait_key",
            "current_content",
            "proposed_content",
            "reason",
            "confidence",
            "risk_level",
            "status",
            "evidence",
            "created_at",
            "reviewed_at",
          ].join(",")
        )
        .eq(
          "scope",
          "user"
        )
        .eq(
          "user_id",
          userData.user.id
        )
        .eq(
          "status",
          status
        )
        .order(
          "created_at",
          {
            ascending: false,
          }
        )
        .limit(50);

    if (error) {
      console.error(
        "EVOLUTION CANDIDATE LIST ERROR:",
        error
      );

      return Response.json(
        {
          error:
            "Failed to load evolution candidates.",
        },
        {
          status: 500,
        }
      );
    }

    return Response.json({
      candidates:
        data ?? [],
    });
  } catch (error) {
    console.error(
      "EVOLUTION CANDIDATE LIST ROUTE ERROR:",
      error
    );

    return Response.json(
      {
        error:
          "Failed to load evolution candidates.",
      },
      {
        status: 500,
      }
    );
  }
}

import {
  createAuthenticatedSupabase,
  getBearerToken,
} from "../_auth";

type ReviewAction =
  | "approve"
  | "reject";

function isReviewAction(
  value: unknown
): value is ReviewAction {
  return (
    value ===
      "approve" ||
    value ===
      "reject"
  );
}

export async function POST(
  request: Request
) {
  try {
    const accessToken =
      getBearerToken(
        request
      );

    if (!accessToken) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const supabase =
      createAuthenticatedSupabase(
        accessToken
      );

    const {
      data: userData,
      error: userError,
    } =
      await supabase.auth.getUser(
        accessToken
      );

    if (
      userError ||
      !userData.user
    ) {
      return Response.json(
        {
          error:
            "Authentication required.",
        },
        {
          status: 401,
        }
      );
    }

    const body =
      await request.json();

    const candidateId =
      typeof body?.candidateId ===
        "string"
        ? body.candidateId.trim()
        : "";

    const action =
      body?.action;

    if (
      !candidateId ||
      !isReviewAction(
        action
      )
    ) {
      return Response.json(
        {
          error:
            "candidateId and valid action are required.",
        },
        {
          status: 400,
        }
      );
    }

    const {
      data,
      error,
    } =
      await supabase.rpc(
        "review_user_evolution_candidate",
        {
          p_candidate_id:
            candidateId,
          p_action:
            action,
        }
      );

    if (error) {
      console.error(
        "EVOLUTION REVIEW RPC ERROR:",
        error
      );

      const message =
        String(
          error.message ??
          ""
        );

      const status =
        message.includes(
          "candidate not found"
        )
          ? 404
          : message.includes(
              "invalid action"
            )
            ? 400
            : 500;

      return Response.json(
        {
          error:
            "Evolution review failed.",
        },
        {
          status,
        }
      );
    }

    return Response.json({
      reviewed: true,
      result:
        data,
    });
  } catch (error) {
    console.error(
      "EVOLUTION REVIEW ROUTE ERROR:",
      error
    );

    return Response.json(
      {
        reviewed: false,
        error:
          "Evolution review failed.",
      },
      {
        status: 500,
      }
    );
  }
}

import { timingSafeEqual } from "node:crypto";
import { createClient } from "@supabase/supabase-js";
import webpush from "web-push";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 60;

// A signed delivery ID authorizes only a persisted body-clock notification.
// The VAPID private key stays in Vercel and is never returned or copied.
export async function POST(request: Request) {
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!key) return Response.json({ error: "admin_config_missing" }, { status: 503 });
  const timestamp = request.headers.get("x-body-clock-time") || "";
  const signature = request.headers.get("x-body-clock-signature") || "";
  if (!/^\d{13}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000 || !/^[a-f0-9]{64}$/.test(signature)) {
    return Response.json({ error: "unauthorized" }, { status: 401 });
  }
  const body = await request.json().catch(() => null);
  const deliveryId = body?.deliveryId;
  if (typeof deliveryId !== "string" || (deliveryId !== "health" && !/^[a-f0-9-]{36}$/i.test(deliveryId))) {
    return Response.json({ error: "invalid_delivery" }, { status: 400 });
  }
  const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL || "https://tzozajnwznxqgxnjikoy.supabase.co", key, {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { fetch: (input, init) => fetch(input, { ...init, signal: AbortSignal.timeout(10000) }) },
  });
  const { data: signed, error: signError } = await db.rpc("sign_misaki_body_clock_relay", { p_timestamp: timestamp, p_delivery_id: deliveryId });
  if (signError || typeof signed !== "string" || !/^[a-f0-9]{64}$/.test(signed)) {
    return Response.json({ error: "relay_auth_unavailable" }, { status: 503 });
  }
  const expected = Buffer.from(signed, "hex");
  if (!timingSafeEqual(expected, Buffer.from(signature, "hex"))) {
    return Response.json({ error: "unauthorized" }, { status: 401 });
  }
  const publicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY || process.env.VAPID_PUBLIC_KEY;
  const privateKey = process.env.VAPID_PRIVATE_KEY;
  if (!publicKey || !privateKey) return Response.json({ error: "vapid_missing" }, { status: 503 });
  if (deliveryId === "health") return Response.json({ ok: true, vapid: true });

  try {
    const { data: delivery, error } = await db.from("misaki_proactive_deliveries")
      .select("id,user_id,message,photo_context,delivered_at,status").eq("id", deliveryId).single();
    if (error || !delivery || delivery.photo_context?.source !== "body_clock" || delivery.status !== "delivered") {
      return Response.json({ error: "delivery_not_found" }, { status: 404 });
    }
    if (!delivery.delivered_at || Date.now() - Date.parse(delivery.delivered_at) > 3600000) {
      return Response.json({ error: "delivery_expired" }, { status: 409 });
    }
    const { data: state, error: stateError } = await db.from("background_push_state")
      .select("notifications_enabled").eq("user_id", delivery.user_id).single();
    if (stateError) throw new Error("state_lookup_failed");
    if (!state.notifications_enabled) return Response.json({ sent: 0, removed: 0, failed: 0, skipped: "notifications_disabled" });
    const { data: subscriptions, error: subsError } = await db.from("push_subscriptions")
      .select("id,endpoint,p256dh,auth").eq("user_id", delivery.user_id);
    if (subsError) throw new Error("subscription_lookup_failed");

    // A primary key permits at most one send attempt per delivery, including replays.
    const { error: claimError } = await db.from("misaki_body_clock_push_attempts").insert({ delivery_id: deliveryId });
    if (claimError?.code === "23505") return Response.json({ sent: 0, removed: 0, failed: 0, skipped: "already_attempted" });
    if (claimError) throw new Error("push_claim_failed");
    webpush.setVapidDetails(process.env.VAPID_SUBJECT || "mailto:misaki@example.com", publicKey, privateKey);
    const payload = JSON.stringify({ title: "美咲", body: delivery.message, url: "/chat" });
    let sent = 0, removed = 0, failed = 0;
    await Promise.all((subscriptions || []).map(async (subscription) => {
      try {
        await webpush.sendNotification({ endpoint: subscription.endpoint, keys: { p256dh: subscription.p256dh, auth: subscription.auth } }, payload, { TTL: 3600, timeout: 10000 });
        sent++;
        await db.from("push_subscriptions").update({ last_used_at: new Date().toISOString() }).eq("id", subscription.id);
      } catch (e: unknown) {
        const status = Number((e as { statusCode?: number })?.statusCode);
        if (status === 404 || status === 410) {
          removed++;
          await db.from("push_subscriptions").delete().eq("id", subscription.id);
        } else { failed++; }
      }
    }));
    const result = { sent, removed, failed, ...(!subscriptions?.length ? { skipped: "no_subscription" } : {}) };
    const { error: logError } = await db.from("misaki_body_clock_push_attempts")
      .update({ completed_at: new Date().toISOString(), result }).eq("delivery_id", deliveryId);
    if (logError) throw new Error("push_result_save_failed");
    return Response.json(result, { status: failed ? 502 : 200 });
  } catch {
    return Response.json({ error: "push_relay_failed" }, { status: 500 });
  }
}

"use client";

import { useLayoutEffect, useState, type ReactNode } from "react";
import { supabase } from "../../lib/supabase";
import { bindDeviceUser, clearMisakiDeviceData, DEVICE_USER_KEY, EMAIL_SAVE_USER_KEY } from "../../lib/device-conversation";

const AUTH_KIND_KEY = "misaki-auth-kind";
const BROWSER_SESSION_KEY = "misaki-browser-session";
// This marker intentionally does not use the misaki- prefix because
// clearMisakiDeviceData() removes every misaki-* key.
const LEGACY_OWNERLESS_CLEANUP_KEY = "legacy-ownerless-cache-cleanup-v1";

export default function AnonymousSessionGuard({ children }: { children: ReactNode }) {
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  useLayoutEffect(() => {
    let active = true;
    let initialized = false;

    async function reconcileAuth() {
      try {
        const hadBrowserSession = sessionStorage.getItem(BROWSER_SESSION_KEY) === "1";
        const lastAuthKind = localStorage.getItem(AUTH_KIND_KEY);
        const deviceOwner = localStorage.getItem(DEVICE_USER_KEY);
        const pendingOwner = localStorage.getItem(EMAIL_SAVE_USER_KEY);
        const legacyCleanupDone = localStorage.getItem(LEGACY_OWNERLESS_CLEANUP_KEY) === "1";
        const { data, error } = await supabase.auth.getSession();
        if (error) throw error;
        if (!active) return;
        let user = data.session?.user ?? null;
        const pendingSave = Boolean(user && pendingOwner === user.id);

        // Old builds could leave conversation/memory behind without an owner marker.
        // Clean that legacy state only once. After this browser has been migrated,
        // a temporarily missing owner marker must never erase a live conversation.
        if (!legacyCleanupDone) {
          if (!deviceOwner && !pendingSave) {
            clearMisakiDeviceData();
          }
          localStorage.setItem(LEGACY_OWNERLESS_CLEANUP_KEY, "1");
        }

        // Supabase の匿名セッション自体は localStorage に残るため、
        // ブラウザを閉じた後の新規セッションでは匿名認証も作り直す。
        if (!user || (!hadBrowserSession && lastAuthKind === "anonymous" && user.is_anonymous && !pendingSave)) {
          clearMisakiDeviceData();
          if (user) {
            const { error: signOutError } = await supabase.auth.signOut({ scope: "local" });
            if (signOutError) throw signOutError;
          }
          if (!active) return;
          const { data: anonymousData, error: signInError } = await supabase.auth.signInAnonymously();
          if (signInError) throw signInError;
          if (!active) return;
          user = anonymousData.user;
        }

        if (user) {
          if (!localStorage.getItem(DEVICE_USER_KEY) && !user.is_anonymous) clearMisakiDeviceData();
          bindDeviceUser(user.id);
          localStorage.setItem(
            AUTH_KIND_KEY,
            user.is_anonymous ? "anonymous" : "permanent"
          );
          sessionStorage.setItem(BROWSER_SESSION_KEY, "1");
          initialized = true;
          setReady(true);
        }
      } catch (error) {
        console.error("ANONYMOUS SESSION GUARD ERROR:", error);
        if (active) setFailed(true);
      }
    }

    void reconcileAuth();

    let recoveringAnonymous = false;

    async function recoverAnonymousSessionPreservingCache() {
      if (!active || recoveringAnonymous) return;
      recoveringAnonymous = true;

      try {
        const { data, error } = await supabase.auth.getSession();
        if (error) throw error;
        if (!active) return;

        let user = data.session?.user ?? null;

        if (!user) {
          const { data: anonymousData, error: signInError } =
            await supabase.auth.signInAnonymously();
          if (signInError) throw signInError;
          if (!active) return;
          user = anonymousData.user;
        }

        if (user?.is_anonymous) {
          // Safari などで匿名セッションが一時的に外れても、
          // 進行中の会話・記憶はブラウザ内に残す。
          // bindDeviceUser() は owner 差分時にキャッシュを消すため、
          // この回復経路では owner だけを安全に付け替える。
          localStorage.setItem(DEVICE_USER_KEY, user.id);
          localStorage.setItem(AUTH_KIND_KEY, "anonymous");
          sessionStorage.setItem(BROWSER_SESSION_KEY, "1");
        }
      } catch (error) {
        console.error("ANONYMOUS SESSION RECOVERY ERROR:", error);
      } finally {
        recoveringAnonymous = false;
      }
    }

    const { data: listener } = supabase.auth.onAuthStateChange((event, session) => {
      if (!active || !initialized) return;
      const user = session?.user;
      const authKind = localStorage.getItem(AUTH_KIND_KEY);
      const owner = localStorage.getItem(DEVICE_USER_KEY);

      if (event === "SIGNED_OUT") {
        if (authKind === "anonymous") {
          // 匿名利用中の一時的な SIGNED_OUT でページを再読み込みすると、
          // 送信中の返答とブラウザ内だけの会話が失われる。
          // 明示的な恒久アカウントのログアウトは account/page.tsx 側で
          // clear + navigation しているので、ここでは匿名だけ回復させる。
          window.setTimeout(() => {
            void recoverAnonymousSessionPreservingCache();
          }, 0);
          return;
        }

        clearMisakiDeviceData();
        window.location.reload();
        return;
      }

      if (user && owner !== user.id) {
        if (user.is_anonymous && authKind === "anonymous") {
          // 匿名セッションが同一ブラウザ内で差し替わった場合も、
          // 会話を消さず新しい匿名 owner に付け替える。
          localStorage.setItem(DEVICE_USER_KEY, user.id);
        } else {
          clearMisakiDeviceData();
          window.location.reload();
          return;
        }
      }

      if (user) {
        localStorage.setItem(
          AUTH_KIND_KEY,
          user.is_anonymous ? "anonymous" : "permanent"
        );
      }
    });

    return () => {
      active = false;
      listener.subscription.unsubscribe();
    };
  }, []);

  if (!ready) return <main>{failed ? "アカウントを確認できませんでした。画面を再読み込みしてください。" : "アカウントを確認しています…"}</main>;
  return <>{children}</>;
}

"use client";
import { useEffect } from "react";
import { supabase } from "../../lib/supabase";
import { DEVICE_USER_KEY, EMAIL_SAVE_USER_KEY } from "../../lib/device-conversation";

const CHAT_HISTORY_KEY = "misaki-chat-history";
const AUTH_KIND_KEY = "misaki-auth-kind";
function readHistory(): any[] {
  try { const value = JSON.parse(localStorage.getItem(CHAT_HISTORY_KEY) || "[]"); return Array.isArray(value) ? value : []; }
  catch { return []; }
}
function sameHistory(a: any[], b: any[]) {
  return a.length === b.length && a.every((item, i) => item?.role === b[i]?.role && item?.text === b[i]?.text);
}
export default function ConversationHistorySync() {
  useEffect(() => {
    let stopped = false, syncing = false, permanentlyDisabled = false;
    const sync = async () => {
      if (stopped || syncing || permanentlyDisabled || sessionStorage.getItem("misaki-chat-sending")) return;
      // Anonymous history is carried by the temporary canonical root. Never start
      // the permanent history GET path for a browser known to be anonymous.
      if (localStorage.getItem(AUTH_KIND_KEY) === "anonymous") return;
      syncing = true;
      try {
        const { data, error } = await supabase.auth.getSession();
        if (error) throw error;
        const session = data.session;
        if (!session?.access_token || session.user.is_anonymous) return;
        const userId = session.user.id;
        if (localStorage.getItem(DEVICE_USER_KEY) !== userId) return;
        const before = readHistory();
        const response = await fetch("/api/persona/history?source=conversation-history-sync", {
          headers: { Authorization: `Bearer ${session.access_token}` }, cache: "no-store",
        });
        if (!response.ok) throw new Error("Conversation state load failed");
        const state = await response.json();
        if (state?.ephemeral === true) {
          permanentlyDisabled = true;
          localStorage.setItem(AUTH_KIND_KEY, "anonymous");
          return;
        }
        if (!state || state.exists !== true || !Array.isArray(state.history) || !Array.isArray(state.memory)) return;
        const { data: latest } = await supabase.auth.getSession();
        if (stopped || latest.session?.user.id !== userId || latest.session.user.is_anonymous ||
          localStorage.getItem(DEVICE_USER_KEY) !== userId || sessionStorage.getItem("misaki-chat-sending") ||
          !sameHistory(before, readHistory())) return;
        window.dispatchEvent(new CustomEvent("misaki-root-state", { detail: state }));
        // Usage convergence is best-effort. A transient quota RPC failure must
        // never block the canonical history/cache refresh below.
        try {
          const { data: usageData, error: usageError } = await supabase.rpc("get_daily_message_usage");
          if (usageError) throw usageError;
          const usage = Array.isArray(usageData) ? usageData[0] : usageData;
          if (usage && typeof usage === "object") {
            window.dispatchEvent(new CustomEvent("misaki-usage-state", { detail: {
              messageCount: typeof usage.message_count === "number" ? usage.message_count : undefined,
              remaining: typeof usage.remaining === "number" ? usage.remaining : undefined,
              isPremium: usage.is_premium === true,
            } }));
          }
        } catch (usageError) {
          console.error("USAGE STATE REFRESH ERROR", usageError);
        }
        localStorage.removeItem(EMAIL_SAVE_USER_KEY);
        if (sameHistory(before, state.history)) return;
        // Keep a pending/failed local user bubble. Successful turns are already
        // committed by the server. A display cache is never uploaded as root state.
        if (before.length > state.history.length && sameHistory(before.slice(0, state.history.length), state.history)) return;
        localStorage.setItem(CHAT_HISTORY_KEY, JSON.stringify(state.history));
        // Canonical history refresh must never hard-reload the chat page.
        // A reload remounts this sync component and can create a reload/fetch loop
        // while auth and the display cache are converging (especially on Chrome).
        window.dispatchEvent(new CustomEvent("misaki-history-state", { detail: state.history }));
      } catch (error) { console.error("CONVERSATION HISTORY SYNC ERROR", error); }
      finally { syncing = false; }
    };
    void sync();
    // Canonical history is refreshed on mount, foreground/focus and auth changes.
    // Do not poll every 5 seconds: normal chat updates locally after commit, while
    // Body Clock/background additions are picked up when the user returns.
    const visible = () => { if (document.visibilityState === "visible") void sync(); };
    window.addEventListener("focus", sync);
    document.addEventListener("visibilitychange", visible);
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      if (!session?.user || session.user.is_anonymous) return;
      window.setTimeout(() => void sync(), 100);
    });
    return () => { stopped = true; window.removeEventListener("focus", sync);
      document.removeEventListener("visibilitychange", visible); listener.subscription.unsubscribe(); };
  }, []);
  return null;
}

export const TEMPORARY_STATE_KEY = "misaki-temporary-state-v1";
export const DEVICE_USER_KEY = "misaki-device-user-id";
export const EMAIL_SAVE_USER_KEY = "misaki-email-save-user-id";

export function clearMisakiDeviceData() {
  for (const storage of [localStorage, sessionStorage]) {
    for (let i = storage.length - 1; i >= 0; i -= 1) {
      const key = storage.key(i);
      if (key?.startsWith("misaki-")) storage.removeItem(key);
    }
  }
}

export function bindDeviceUser(userId: string) {
  const owner = localStorage.getItem(DEVICE_USER_KEY);
  if (owner && owner !== userId) clearMisakiDeviceData();
  localStorage.setItem(DEVICE_USER_KEY, userId);
}

export function readDeviceArray(key: string): unknown[] {
  const raw = localStorage.getItem(key);
  if (!raw) return [];
  const value: unknown = JSON.parse(raw);
  if (!Array.isArray(value)) throw new Error("Invalid conversation cache.");
  return value;
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { analyzeUserEvolution, type ExistingRelationshipTrait } from "./evolution-analyzer";
import type { ChatMessage } from "../user-profile";

export type EvolutionRunResult = {
  analyzed: boolean;
  skipped: boolean;
  reason: "manual" | "claimed" | "insufficient_history" | "cadence_not_due" | "analysis_failed";
  saved: number;
};

function buildFingerprint(history: ChatMessage[]) {
  const source = history
    .filter((item) => item.role === "user")
    .slice(-20)
    .map((item) => item.text.trim())
    .join("\n");

  let hash = 2166136261;
  for (let i = 0; i < source.length; i += 1) {
    hash ^= source.charCodeAt(i);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return `u-${source.length}-${hash.toString(16)}`;
}

async function loadExistingTraits(
  supabase: SupabaseClient,
  userId: string
): Promise<ExistingRelationshipTrait[]> {
  const { data, error } = await supabase
    .from("misaki_user_relationship_traits")
    .select("trait_key, content, strength")
    .eq("user_id", userId)
    .limit(20);

  if (error) {
    console.error("EVOLUTION TRAIT READ ERROR:", error);
    return [];
  }

  return Array.isArray(data)
    ? data.map((row) => ({
        trait_key: String(row.trait_key ?? ""),
        content: String(row.content ?? ""),
        strength:
          typeof row.strength === "number"
            ? row.strength
            : row.strength != null
              ? Number(row.strength)
              : null,
      }))
    : [];
}

async function claimAnalysisSlot(
  supabase: SupabaseClient,
  history: ChatMessage[]
) {
  const { data, error } = await supabase.rpc(
    "claim_user_evolution_analysis",
    {
      p_fingerprint: buildFingerprint(history),
      p_min_hours: 12,
    }
  );

  if (error) {
    console.error("EVOLUTION CLAIM ERROR:", error);
    return false;
  }

  return data === true;
}

async function saveCandidates(
  supabase: SupabaseClient,
  existingTraits: ExistingRelationshipTrait[],
  candidates: Awaited<ReturnType<typeof analyzeUserEvolution>>
) {
  const currentByTrait = new Map(
    existingTraits.map((trait) => [trait.trait_key, trait.content])
  );

  let saved = 0;

  for (const candidate of candidates) {
    const { error } = await supabase.rpc(
      "create_user_evolution_candidate",
      {
        p_trait_key: candidate.traitKey,
        p_current_content:
          currentByTrait.get(candidate.traitKey) ?? null,
        p_proposed_content: candidate.proposedContent,
        p_reason: candidate.reason,
        p_confidence: candidate.confidence,
        p_risk_level: candidate.riskLevel,
        p_evidence: {
          quotes: candidate.evidence,
          source: "conversation_analysis",
          analyzer: "gemini-3.1-flash-lite",
        },
      }
    );

    if (error) {
      console.error("EVOLUTION CANDIDATE SAVE ERROR:", error);
      continue;
    }
    saved += 1;
  }

  return saved;
}

export async function runUserEvolutionAnalysis(
  supabase: SupabaseClient,
  userId: string,
  apiKey: string,
  history: ChatMessage[],
  memory: string[],
  options?: { force?: boolean }
): Promise<EvolutionRunResult> {
  try {
    const force = options?.force === true;
    const userMessageCount = history.filter(
      (item) => item.role === "user"
    ).length;

    if (!force && userMessageCount < 8) {
      return {
        analyzed: false,
        skipped: true,
        reason: "insufficient_history",
        saved: 0,
      };
    }

    if (!force) {
      const claimed = await claimAnalysisSlot(supabase, history);
      if (!claimed) {
        return {
          analyzed: false,
          skipped: true,
          reason: "cadence_not_due",
          saved: 0,
        };
      }
    }

    const existingTraits = await loadExistingTraits(supabase, userId);
    const candidates = await analyzeUserEvolution(
      apiKey,
      history,
      memory,
      existingTraits
    );
    const saved = await saveCandidates(
      supabase,
      existingTraits,
      candidates
    );

    return {
      analyzed: true,
      skipped: false,
      reason: force ? "manual" : "claimed",
      saved,
    };
  } catch (error) {
    console.error("EVOLUTION RUNNER ERROR:", error);
    return {
      analyzed: false,
      skipped: false,
      reason: "analysis_failed",
      saved: 0,
    };
  }
}

import type {
  SupabaseClient,
} from "@supabase/supabase-js";

import {
  createFallbackPersonaPrompt,
  type PersonaChannel,
} from "./fallback-persona";

import {
  createRelationshipTimeGuide,
  type RelationshipTimeContext,
} from "../relationship-time";
import { createRelationshipEmotionGuide } from "../relationship-emotion";
import { createRelationshipActionGuide } from "../relationship-action";

type PromptModuleRow = {
  module_key: string;
  content: string;
  sort_order: number;
  metadata:
    | Record<string, unknown>
    | null;
};

type PersonaCacheEntry = {
  expiresAt: number;
  versionCode: string;
  modules: PromptModuleRow[];
};

export type LoadedPersonaPrompt = {
  text: string;
  source:
    | "database"
    | "fallback";
  versionCode:
    | string
    | null;
};

const CACHE_TTL_MS =
  5 * 60 * 1000;

let globalCache:
  PersonaCacheEntry | null =
    null;

function moduleSupportsChannel(
  module: PromptModuleRow,
  channel: PersonaChannel
) {
  const channels =
    module.metadata?.channels;

  if (!Array.isArray(channels)) {
    return true;
  }

  return channels.some(
    (value) =>
      value === channel
  );
}

async function loadActiveGlobalModules(
  supabase: SupabaseClient
) {
  const now = Date.now();

  if (
    globalCache &&
    globalCache.expiresAt > now
  ) {
    return globalCache;
  }

  const {
    data: versions,
    error: versionError,
  } =
    await supabase
      .from(
        "misaki_persona_versions"
      )
      .select(
        "id, version_code"
      )
      .eq(
        "status",
        "active"
      )
      .order(
        "activated_at",
        {
          ascending: false,
          nullsFirst: false,
        }
      )
      .limit(1);

  if (versionError) {
    throw versionError;
  }

  const version =
    versions?.[0];

  if (!version) {
    throw new Error(
      "No active Misaki persona version"
    );
  }

  const {
    data: modules,
    error: modulesError,
  } =
    await supabase
      .from(
        "misaki_prompt_modules"
      )
      .select(
        "module_key, content, sort_order, metadata"
      )
      .eq(
        "version_id",
        version.id
      )
      .order(
        "sort_order",
        {
          ascending: true,
        }
      );

  if (modulesError) {
    throw modulesError;
  }

  const entry:
    PersonaCacheEntry = {
    expiresAt:
      now + CACHE_TTL_MS,
    versionCode:
      version.version_code,
    modules:
      (modules ?? []) as
        PromptModuleRow[],
  };

  globalCache = entry;

  return entry;
}

async function loadUserRelationshipTraits(
  supabase: SupabaseClient,
  userId: string
) {
  const {
    data,
    error,
  } =
    await supabase
      .from(
        "misaki_user_relationship_traits"
      )
      .select(
        "trait_key, content, strength"
      )
      .eq(
        "user_id",
        userId
      )
      .order(
        "strength",
        {
          ascending: false,
        }
      )
      .limit(20);

  if (error) {
    throw error;
  }

  if (
    !data ||
    data.length === 0
  ) {
    return "";
  }

  return `
【このユーザーとの関係で育った特徴】

${data
  .map(
    (trait) =>
      `・${trait.content}`
  )
  .join("\n")}

これはこのユーザーとの関係だけに使ってください。
他のユーザーや美咲全体の固定人格へ広げないでください。
`.trim();
}

function createRelationshipContinuityGuide(
  context: RelationshipTimeContext | null
) {
  try {
    return [
      createRelationshipTimeGuide(context),
      createRelationshipEmotionGuide(context),
      createRelationshipActionGuide(context),
    ]
      .filter(Boolean)
      .join("\n\n");
  } catch (error) {
    console.error(
      "RELATIONSHIP CONTINUITY GUIDE FALLBACK:",
      error
    );

    return "";
  }
}

export async function loadPersonaPrompt(
  supabase: SupabaseClient,
  userId: string,
  channel: PersonaChannel,
  relationshipTimeContext: RelationshipTimeContext | null = null
): Promise<LoadedPersonaPrompt> {
  try {
    const [
      active,
      userTraits,
      relationshipContinuityGuide,
    ] =
      await Promise.all([
        loadActiveGlobalModules(
          supabase
        ),
        loadUserRelationshipTraits(
          supabase,
          userId
        ),
        Promise.resolve(
          createRelationshipContinuityGuide(
            relationshipTimeContext
          )
        ),
      ]);

    const globalText =
      active.modules
        .filter(
          (module) =>
            moduleSupportsChannel(
              module,
              channel
            )
        )
        .map(
          (module) =>
            module.content.trim()
        )
        .filter(Boolean)
        .join("\n\n");

    if (!globalText) {
      throw new Error(
        "Active persona has no usable prompt modules"
      );
    }

    return {
      text:
        [
          globalText,
          userTraits,
          relationshipContinuityGuide,
        ]
          .filter(Boolean)
          .join("\n\n"),
      source: "database",
      versionCode:
        active.versionCode,
    };
  } catch (error) {
    console.error(
      "PERSONA DB FALLBACK:",
      error
    );

    return {
      text:
        createFallbackPersonaPrompt(
          channel
        ),
      source: "fallback",
      versionCode: null,
    };
  }
}

