  globalCache = null;
}

import type { RelationshipPatternContext } from "./relationship-emotion-reducer";

type RelationshipEventLike = {
  event_type?: string | null;
  metadata?: unknown;
  created_at?: string | null;
};

type SignalSummary = { name?: string; strength?: number; confidence?: number };

export type RelationshipStoryState = {
  unresolvedHurt: number;
  repairStage: "none" | "hurt" | "repair_attempted" | "rebuilding";
  meaning: "none" | "unresolved_hurt" | "repair_in_progress" | "repair_demonstrated" | "repeated_harm";
  lastMeaningfulAt: string | null;
};

function signalsOf(event: RelationshipEventLike): SignalSummary[] {
  const metadata = event.metadata && typeof event.metadata === "object"
    ? event.metadata as Record<string, unknown>
    : {};
  const raw = metadata.signal_summary ?? metadata.signals;
  return Array.isArray(raw) ? raw.filter((item): item is SignalSummary => !!item && typeof item === "object") : [];
}

function weight(signal: SignalSummary) {
  const strength = Number.isFinite(signal.strength) ? Number(signal.strength) : 0;
  const confidence = Number.isFinite(signal.confidence) ? Number(signal.confidence) : 0;
  return strength * confidence;
}

function orderedEvents(events: RelationshipEventLike[]) {
  return events.slice(0, 40).sort((a,b) => {
    const ta = a.created_at ? Date.parse(a.created_at) : 0;
    const tb = b.created_at ? Date.parse(b.created_at) : 0;
    return ta - tb;
  });
}

/**
 * Read the same persisted relationship events as a small story trajectory.
 * This deliberately stores meaning, not a verbatim grievance: hurt may become
 * "we repaired this" after later evidence, while repeated harm stays cautionary.
 */
export function deriveRelationshipStory(events: RelationshipEventLike[]): RelationshipStoryState {
  let unresolvedHurt = 0;
  let repairStage: RelationshipStoryState["repairStage"] = "none";
  let meaning: RelationshipStoryState["meaning"] = "none";
  let lastMeaningfulAt: string | null = null;
  let harmCount = 0;

  for (const event of orderedEvents(events)) {
    const signals = signalsOf(event);
    const harm = signals.filter(s => String(s.name) === "hurtful").reduce((n,s)=>n+weight(s),0);
    const repair = signals.filter(s => String(s.name) === "repair").reduce((n,s)=>n+weight(s),0);
    const demonstratedCare = signals.filter(s => ["care","trust"].includes(String(s.name))).reduce((n,s)=>n+weight(s),0);

    if (harm >= .45) {
      harmCount += 1;
      unresolvedHurt = Math.min(3, unresolvedHurt + harm);
      repairStage = "hurt";
      meaning = harmCount >= 2 ? "repeated_harm" : "unresolved_hurt";
      lastMeaningfulAt = event.created_at ?? lastMeaningfulAt;
      continue;
    }

    if (repair >= .5 && unresolvedHurt > 0) {
      repairStage = "repair_attempted";
      meaning = "repair_in_progress";
      unresolvedHurt = Math.max(.15, unresolvedHurt - repair * .35);
      lastMeaningfulAt = event.created_at ?? lastMeaningfulAt;
    }

    if (demonstratedCare >= .55 && repairStage === "repair_attempted") {
      repairStage = "rebuilding";
      unresolvedHurt = Math.max(0, unresolvedHurt - demonstratedCare * .75);
      meaning = unresolvedHurt <= .2 ? "repair_demonstrated" : "repair_in_progress";
      lastMeaningfulAt = event.created_at ?? lastMeaningfulAt;
    } else if (demonstratedCare >= .55 && repairStage === "rebuilding") {
      unresolvedHurt = Math.max(0, unresolvedHurt - demonstratedCare * .5);
      if (unresolvedHurt <= .2) meaning = "repair_demonstrated";
      lastMeaningfulAt = event.created_at ?? lastMeaningfulAt;
    }
  }

  return {
    unresolvedHurt: Math.round(unresolvedHurt * 100) / 100,
    repairStage,
    meaning,
    lastMeaningfulAt,
  };
}

/**
 * Derive conservative relationship-learning counters from persisted events.
 * These are evidence summaries, not permanent labels about the user.
 */
export function deriveRelationshipPatterns(events: RelationshipEventLike[]): RelationshipPatternContext {
  let repeatedHarm = 0;
  let reliableRepair = 0;
  let sustainedCare = 0;
  let repairAttemptAt: number | null = null;
  let unresolvedHarmAt: number | null = null;
  let lastHarmAt: number | null = null;
  let lastCareAt: number | null = null;
  let consecutiveHarm = 0;
  let consecutiveCare = 0;
  const now = Date.now();
  const ordered = orderedEvents(events);

  for (const event of ordered) {
    const signals = signalsOf(event);
    const harm = signals.filter(s => String(s.name) === "hurtful").reduce((n,s)=>n+weight(s),0);
    const repair = signals.filter(s => ["repair"].includes(String(s.name))).reduce((n,s)=>n+weight(s),0);
    const care = signals.filter(s => ["care","trust","warmth"].includes(String(s.name))).reduce((n,s)=>n+weight(s),0);
    const at = event.created_at ? Date.parse(event.created_at) : NaN;
    if (!Number.isFinite(at)) continue;
    const ageDays = Math.max(0, (now - at) / 86400000);
    const recency = ageDays <= 30 ? 1 : ageDays <= 90 ? .6 : ageDays <= 180 ? .3 : .1;

    if (harm >= .45) {
      const clustered = lastHarmAt !== null && at - lastHarmAt <= 14 * 86400000;
      const recurrence = repairAttemptAt !== null && at - repairAttemptAt <= 14 * 86400000 ? 1.35 : clustered ? 1.15 : 1;
      consecutiveHarm += 1;
      consecutiveCare = 0;
      repeatedHarm += recency * recurrence * (consecutiveHarm >= 3 ? 1.1 : 1);
      lastHarmAt = at;
      unresolvedHarmAt = at;
      repairAttemptAt = null;
    }
    if (repair >= .5 && harm < .45) {
      const followsRecentHarm = unresolvedHarmAt !== null && at - unresolvedHarmAt <= 30 * 86400000;
      repairAttemptAt = followsRecentHarm ? at : null;
      consecutiveHarm = 0;
    }
    if (care >= .55 && harm < .45) {
      const sustained = lastCareAt !== null && at - lastCareAt <= 30 * 86400000;
      consecutiveCare += 1;
      consecutiveHarm = 0;
      sustainedCare += recency * (sustained ? 1.1 : 1) * (consecutiveCare >= 3 ? 1.05 : 1);
      lastCareAt = at;
      if (repairAttemptAt !== null && at >= repairAttemptAt && at - repairAttemptAt <= 14 * 86400000) {
        reliableRepair += recency;
        repairAttemptAt = null;
        unresolvedHarmAt = null;
      }
    }
  }

  return {
    repeatedHarm: Math.min(Math.round(repeatedHarm * 100) / 100, 3),
    reliableRepair: Math.min(Math.round(reliableRepair * 100) / 100, 3),
    sustainedCare: Math.min(Math.round(sustainedCare * 100) / 100, 3),
  };
}

export async function loadRelationshipHistory(
  supabase: { from: (table: string) => any },
  isAnonymous: boolean
): Promise<{ patterns: RelationshipPatternContext; story: RelationshipStoryState }> {
  if (isAnonymous) return { patterns: {}, story: deriveRelationshipStory([]) };

  const { data, error } = await supabase
    .from("misaki_relationship_events")
    .select("event_type,metadata,created_at")
    .in("event_type", ["emotion_action_v2_after_chat", "temporary_relationship_checkpoint"])
    .order("created_at", { ascending: false })
    .limit(40);

  if (error) {
    console.error("RELATIONSHIP HISTORY LOAD ERROR:", error);
    return { patterns: {}, story: deriveRelationshipStory([]) };
  }

  const events = Array.isArray(data) ? data : [];
  return { patterns: deriveRelationshipPatterns(events), story: deriveRelationshipStory(events) };
}

export async function loadRelationshipPatterns(
  supabase: { from: (table: string) => any },
  isAnonymous: boolean
): Promise<RelationshipPatternContext> {
  return (await loadRelationshipHistory(supabase, isAnonymous)).patterns;
}

export async function loadRelationshipStory(
  supabase: { from: (table: string) => any },
  isAnonymous: boolean
): Promise<RelationshipStoryState> {
  return (await loadRelationshipHistory(supabase, isAnonymous)).story;
}

import { PROCESSING_VERSION, hash, episodeFor, patternsFor, boundedDelta, type Evidence, type Turn, type Episode, type CriticalType } from "./relationship-engine-v1.ts";
import { analyzeRelationshipEvidence, criticalCandidates, validateCriticalEvent } from "./relationship-analyzer-v1.ts";

const phases = ["pending", "analyzing", "evidence_saved", "episode_saved", "pattern_saved", "applied"] as const;
export type ProcessingResult = { status: "completed" } | { status: "deferred"; reason: string };
export interface RelationshipStore {
  claim(userId: string, requestId: string): Promise<{ claimed: boolean; replayed?: boolean; leaseToken?: string; reason?: string }>;
  renew(userId: string, requestId: string, token: string): Promise<void>;
  release(userId: string, requestId: string, token: string): Promise<void>;
  setLeaseGuard?(check?: () => Promise<void>): void;
  turn(userId: string, requestId: string): Promise<Turn>;
  ledger(userId: string, requestId: string): Promise<any>;
  advance(userId: string, requestId: string, phase: string, token: string, error?: string): Promise<void>;
  evidence(userId: string, requestId: string): Promise<Array<{ id: string; evidence_key: string; payload: { candidate: Evidence } }>>;
  saveEvidence(userId: string, turn: Turn, key: string, e: Evidence, token: string): Promise<void>;
  episodes(userId: string): Promise<Array<{ id: string; episode_key: string; summary: { episode: Episode } }>>;
  saveEpisode(userId: string, requestId: string, episode: Episode, evidenceIds: string[], token: string): Promise<void>;
  patterns(userId: string): Promise<Array<{ id: string; pattern_key: string }>>;
  appliedPatterns(userId: string): Promise<string[]>;
  savePattern(userId: string, requestId: string, key: string, episodes: Array<{ id: string; episode: Episode }>, token: string): Promise<void>;
  apply(userId: string, requestId: string, patternIds: string[], delta: ReturnType<typeof boundedDelta>, token: string): Promise<void>;
  events(userId: string): Promise<any[]>;
  pending(userId: string, turn: Turn, type: CriticalType, token: string): Promise<any>;
  advancePending(userId: string, turn: Turn, type: CriticalType, status: string, token: string): Promise<void>;
  applyCritical(userId: string, turn: Turn, type: CriticalType, token: string): Promise<void>;
}

function compact(evidence: Evidence[]) {
  return evidence.map(e => [e.type, e.axis, e.polarity, e.strength, e.confidence, e.interpretation, e.subject, e.supportingTurn]);
}
function expand(rows: any[][]): Evidence[] {
  return rows.map(([type, axis, polarity, strength, confidence, interpretation, subject, supportingTurn]) => ({ type, axis, polarity, strength, confidence, interpretation, subject, supportingTurn } as Evidence));
}

/** Successful conversation is the only entry boundary. Every write is delegated to canonical RPCs. */
export async function processRelationshipTurn(store: RelationshipStore, userId: string, requestId: string,
  analyze = analyzeRelationshipEvidence, validate = validateCriticalEvent,
  prepare?: (check: () => Promise<void>, token: string) => Promise<void>) {
  const owner = store;
  const claim = await owner.claim(userId, requestId);
  // A replayed claim carries another invocation's token, not new ownership.
  // Lost claim responses safely wait for expiry rather than adopting that token.
  if (!claim.claimed || claim.replayed) return { status: "deferred", reason: claim.reason ?? "lease_busy" } as ProcessingResult;
  if (!claim.leaseToken) throw new Error("relationship_claim_token_required");
  const token = claim.leaseToken;
  let lost = false;
  const check = async () => {
    if (lost) throw new Error("relationship_processing_lease_lost");
    try { await owner.renew(userId, requestId, token); }
    catch { lost = true; throw new Error("relationship_processing_lease_lost"); }
  };
  // Read guards detect lease loss early; every mutation also carries ownership
  // into its v2 RPC for transactional DB validation, closing the check/write gap.
  store = new Proxy(owner, { get(target, key) {
    const value = Reflect.get(target, key);
    if (typeof value !== "function") return value;
    return async (...args: unknown[]) => { await check(); return value.apply(target, args); };
  } });
  const guardedExternal = async <T>(work: () => Promise<T>) => {
    await check();
    const result = await work();
    await check();
    return result;
  };
  owner.setLeaseGuard?.(check);
  let stage = "pending";
  let candidates: Evidence[] | undefined;
  try {
    const turn = await store.turn(userId, requestId); // Reject unsaved/cross-user turns before any model/write.
    const ledger = await store.ledger(userId, requestId);
    if (ledger?.status === "applied") return { status: "completed" } as ProcessingResult;
    stage = ledger?.status ?? "pending";
    if (prepare) await guardedExternal(() => prepare(check, token));
    if (stage === "failed") {
      const journal = JSON.parse(ledger.last_error ?? "{}");
      stage = phases.includes(journal.stage) ? journal.stage : "analyzing";
      candidates = journal.evidence ? expand(journal.evidence) : undefined;
      await store.advance(userId, requestId, "analyzing", token);
      // The control RPC restarts at analyzing; recover completed stages without re-running them.
      for (const phase of phases.slice(2, phases.indexOf(stage as any) + 1)) await store.advance(userId, requestId, phase, token);
    }
    if (stage === "pending") { await store.advance(userId, requestId, "analyzing", token); stage = "analyzing"; }
    // Pending is durable BEFORE the external validator. Evidence cannot manufacture critical events.
    const events = await store.events(userId);
    for (const type of criticalCandidates(turn.message)) {
      if (events.some(e => e.request_id === requestId && e.event_type === type)) continue;
      const pending = await store.pending(userId, turn, type, token);
      if (["resolved", "dismissed"].includes(pending.status)) continue;
      await store.advancePending(userId, turn, type, "processing", token);
      try {
        if (await guardedExternal(() => validate(turn, type, events))) await store.applyCritical(userId, turn, type, token);
        else await store.advancePending(userId, turn, type, "dismissed", token);
      } catch (error) {
        if (lost || /relationship_processing_lease_(lost|required)/.test(String(error))) throw error;
        await store.advancePending(userId, turn, type, "failed", token);
        throw error;
      }
    }
    if (stage === "analyzing") {
      candidates ??= await guardedExternal(() => analyze(turn));
      const saved = await store.evidence(userId, requestId);
      for (const e of candidates) {
        const key = hash(`${e.type}:${e.axis}:${e.polarity}`);
        if (!saved.some(x => x.evidence_key === key)) await store.saveEvidence(userId, turn, key, e, token);
      }
      await store.advance(userId, requestId, "evidence_saved", token); stage = "evidence_saved";
    }
    if (stage === "evidence_saved") {
      const saved = await store.evidence(userId, requestId);
      for (const item of saved) {
        const episode = episodeFor(item.payload.candidate, turn);
        if (episode) await store.saveEpisode(userId, requestId, episode, [item.id], token);
      }
      await store.advance(userId, requestId, "episode_saved", token); stage = "episode_saved";
    }
    if (stage === "episode_saved") {
      const episodes = await store.episodes(userId);
      const existing = await store.patterns(userId);
      const patterns = patternsFor(episodes.map(e => e.summary.episode), await store.appliedPatterns(userId));
      for (const p of patterns) {
        if (!existing.some(x => x.pattern_key === p.key)) await store.savePattern(userId, requestId, p.key,
          p.episodes.map(e => ({ id: episodes.find(x => x.episode_key === e.key)!.id, episode: e })), token);
      }
      await store.advance(userId, requestId, "pattern_saved", token); stage = "pattern_saved";
    }
    if (stage === "pattern_saved") {
      const episodes = await store.episodes(userId);
      const patterns = patternsFor(episodes.map(e => e.summary.episode), await store.appliedPatterns(userId));
      const saved = await store.patterns(userId);
      if (patterns.length) await store.apply(userId, requestId, patterns.map(p => {
        const id = saved.find(x => x.pattern_key === p.key)?.id;
        if (!id) throw new Error("canonical_pattern_missing");
        return id;
      }), boundedDelta(patterns), token);
      // No Pattern means no State RPC, including no version-only mutation.
      await store.advance(userId, requestId, "applied", token);
    }
    return { status: "completed" } as ProcessingResult;
  } catch (error) {
    if (lost || /relationship_processing_lease_(lost|required)/.test(String(error))) return { status: "deferred", reason: "lease_lost" } as ProcessingResult;
    const journal = JSON.stringify({ stage, evidence: candidates ? compact(candidates) : undefined, error: "relationship_processing_failed" });
    if (journal.length > 1900) throw new Error("relationship_retry_journal_too_large");
    try { await store.advance(userId, requestId, "failed", token, journal); }
    catch (failure) { if (lost || /relationship_processing_lease_(lost|required)/.test(String(failure))) return { status: "deferred", reason: "lease_lost" } as ProcessingResult; throw failure; }
    throw error;
  } finally {
    owner.setLeaseGuard?.();
    // Token-specific release cannot remove a reclaimed successor's lease.
    try { await owner.release(userId, requestId, token); }
    catch { console.error("RELATIONSHIP LEASE RELEASE RETRY REQUIRED"); }
  }
}

export class CanonicalRelationshipStore implements RelationshipStore {
  private db: any;
  private leaseGuard?: () => Promise<void>;
  setLeaseGuard(check?: () => Promise<void>) { this.leaseGuard = check; }
  constructor(db: any) { this.db = db; }
  async rpc(name: string, args: Record<string, unknown>) {
    if (!/^(claim_misaki_relationship_processing_v1|renew_misaki_relationship_processing_lease_v1|release_misaki_relationship_processing_lease_v1)$/.test(name)) await this.leaseGuard?.();
    const { data, error } = await this.db.rpc(name, args);
    if (error) throw new Error(`${name}_failed:${error.code ?? ""}:${error.message ?? ""}`);
    return data;
  }
  async claim(userId: string, requestId: string) {
    const boundary = process.env.MISAKI_RELATIONSHIP_ENGINE_START_AT;
    if (!boundary || !Number.isFinite(Date.parse(boundary))) throw new Error("relationship_start_boundary_required");
    return this.rpc("claim_misaki_relationship_processing_v1", { p_user_id: userId, p_request_id: requestId,
      p_processing_version: PROCESSING_VERSION, p_start_at: boundary, p_lease_seconds: 120 });
  }
  async renew(userId: string, requestId: string, token: string) {
    await this.rpc("renew_misaki_relationship_processing_lease_v1", { p_user_id: userId, p_request_id: requestId,
      p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_lease_seconds: 120 });
  }
  async release(userId: string, requestId: string, token: string) {
    await this.rpc("release_misaki_relationship_processing_lease_v1", { p_user_id: userId, p_request_id: requestId,
      p_processing_version: PROCESSING_VERSION, p_lease_token: token });
  }
  async rows(table: string, userId: string, configure: (query: any) => any = q => q) {
    const rows: any[] = [];
    const key = table === "misaki_relationship_pattern_consumptions" ? "pattern_id" : table === "misaki_relationship_episode_evidence" ? "evidence_id" : ["misaki_relationship_processing", "misaki_relationship_state_applications"].includes(table) ? "request_id" : "id";
    for (let offset = 0; ; offset += 500) {
      await this.leaseGuard?.();
      const { data, error } = await configure(this.db.from(table).select("*").eq("user_id", userId)).order(key, { ascending: true }).range(offset, offset + 499);
      if (error) throw new Error(`${table}_read_failed`);
      rows.push(...(data ?? []));
      if (!data || data.length < 500) return rows;
    }
  }
  async turn(userId: string, requestId: string): Promise<Turn> {
    const rows = await this.rows("misaki_relationship_events", userId, q => q.eq("request_id", requestId).eq("event_type", "chat_turn_completed"));
    const e = rows[0];
    if (!e || typeof e.metadata?.message !== "string" || typeof e.metadata?.result?.reply !== "string") throw new Error("canonical_chat_turn_required");
    return { requestId, message: e.metadata.message, reply: e.metadata.result.reply, savedAt: e.created_at };
  }
  async ledger(userId: string, requestId: string) {
    return (await this.rows("misaki_relationship_processing", userId, q => q.eq("request_id", requestId).eq("processing_version", PROCESSING_VERSION)))[0];
  }
  async advance(userId: string, requestId: string, phase: string, token: string, error?: string) {
    await this.rpc("advance_misaki_relationship_processing_v2", { p_user_id: userId, p_request_id: requestId, p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_status: phase, p_last_error: error ?? null });
  }
  evidence(userId: string, requestId: string) {
    return this.rows("misaki_relationship_evidence", userId, q => q.eq("request_id", requestId).eq("analyzer_version", PROCESSING_VERSION));
  }
  async saveEvidence(userId: string, turn: Turn, key: string, e: Evidence, token: string) {
    await this.rpc("record_misaki_relationship_evidence_v2", { p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_request_id: turn.requestId, p_evidence_key: key,
      p_axis: e.axis, p_direction: e.polarity, p_strength: e.strength, p_interpretation: e.interpretation, p_subject: e.subject,
      p_payload: { candidate: e, supporting_request_id: turn.requestId, evidence_type: e.type, confidence: e.confidence }, p_analyzer_version: PROCESSING_VERSION });
  }
  episodes(userId: string) { return this.rows("misaki_relationship_episodes", userId, q => q.eq("analyzer_version", PROCESSING_VERSION)); }
  async saveEpisode(userId: string, requestId: string, episode: Episode, evidenceIds: string[], token: string) {
    const existing = (await this.episodes(userId)).find(x => x.episode_key === episode.key);
    const links = existing ? await this.rows("misaki_relationship_episode_evidence", userId, q => q.eq("episode_id", existing.id)) : [];
    if (evidenceIds.every(id => links.some(x => x.evidence_id === id))) return;
    await this.rpc("upsert_misaki_relationship_episode_v2", { p_request_id: requestId, p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_episode_key: episode.key, p_episode_type: episode.type,
      p_analyzer_version: PROCESSING_VERSION, p_first_request_id: existing?.first_request_id ?? episode.requestId, p_last_request_id: episode.requestId,
      p_evidence_ids: evidenceIds, p_summary: { episode: existing?.summary?.episode ?? episode } });
  }
  patterns(userId: string) { return this.rows("misaki_relationship_patterns", userId, q => q.eq("pattern_version", PROCESSING_VERSION)); }
  async appliedPatterns(userId: string) {
    const applications = await this.rows("misaki_relationship_pattern_consumptions", userId, q => q.eq("processing_version", PROCESSING_VERSION));
    const ids = new Set(applications.map(a => a.pattern_id));
    return (await this.patterns(userId)).filter(p => ids.has(p.id)).map(p => p.pattern_key);
  }
  async savePattern(userId: string, requestId: string, key: string, episodes: Array<{ id: string; episode: Episode }>, token: string) {
    await this.rpc("upsert_misaki_relationship_pattern_v2", { p_request_id: requestId, p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_pattern_key: key, p_pattern_type: episodes[0].episode.type,
      p_pattern_version: PROCESSING_VERSION, p_episode_ids: episodes.map(e => e.id), p_first_request_id: episodes[0].episode.requestId,
      p_last_request_id: episodes[episodes.length - 1].episode.requestId, p_summary: { policy: "three_distinct_days_v1", axis: episodes[0].episode.axis, polarity: episodes[0].episode.polarity } });
  }
  async apply(userId: string, requestId: string, patternIds: string[], delta: ReturnType<typeof boundedDelta>, token: string) {
    await this.rpc("apply_misaki_relationship_state_v2", { p_user_id: userId, p_request_id: requestId, p_processing_version: PROCESSING_VERSION,
      p_lease_token: token, p_pattern_ids: patternIds, ...Object.fromEntries(Object.entries(delta).map(([axis, value]) => [`p_${axis}_delta`, value])) });
  }
  events(userId: string) { return this.rows("misaki_relationship_events", userId, q => q.in("event_type", ["romantic_proposal", "romantic_acceptance", "romantic_rejection", "relationship_end", "boundary_event", "reconciliation"]).order("id", { ascending: true })); }
  pending(userId: string, turn: Turn, type: CriticalType, token: string) {
    return this.rpc("upsert_misaki_relationship_critical_pending_v2", { p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_request_id: turn.requestId, p_candidate_type: type, p_context: { source: "canonical_turn", request_id: turn.requestId }, p_validator_version: PROCESSING_VERSION });
  }
  async advancePending(userId: string, turn: Turn, type: CriticalType, status: string, token: string) {
    await this.rpc("advance_misaki_relationship_critical_pending_v2", { p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_request_id: turn.requestId, p_candidate_type: type, p_status: status, p_validator_version: PROCESSING_VERSION, p_last_error: status === "failed" ? "validator_failed" : null });
  }
  async applyCritical(userId: string, turn: Turn, type: CriticalType, token: string) {
    await this.rpc("apply_misaki_relationship_critical_event_v2", { p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_user_id: userId, p_request_id: turn.requestId, p_event_type: type, p_validator_version: PROCESSING_VERSION, p_reason: "explicit_event_validated", p_metadata: { processing_version: PROCESSING_VERSION } });
  }
}

import { createServerSupabase, loadTemporaryRoot, editTemporaryRoot, openTemporaryState, type RootState } from "./canonical-state";
import { createLegacyRelationshipActingState } from "./relationship-acting-guide";
import { engineEnabled, PROCESSING_VERSION, applyTemporaryEvidence, AXES, type Snapshot, type Turn } from "./relationship-engine-v1";
import { analyzeRelationshipEvidence, criticalCandidates, validateCriticalEvent } from "./relationship-analyzer-v1";
import { CanonicalRelationshipStore, processRelationshipTurn } from "./relationship-processing-v1";
import { createGeminiTelemetrySink } from "./gemini-usage-telemetry-server";

// Local deduplication is an optimization; DB leases serialize distributed workers.
const running = new Map<string, Promise<void>>();
export function enqueueTemporaryTurn(root: RootState, turn: Turn): Snapshot | undefined {
  if (!engineEnabled()) return root.relationshipEngine;
  const snapshot = root.relationshipEngine ?? { state: createLegacyRelationshipActingState(root.relationshipPoints), version: 0, episodes: [], appliedPatterns: [], processed: [], pending: [], criticalEvents: [] };
  return snapshot.processed.includes(turn.requestId) || snapshot.pending.some(t => t.requestId === turn.requestId)
    ? snapshot : { ...snapshot, pending: [...snapshot.pending, turn] };
}

async function analyzeTemporarySnapshot(root: RootState, save?: (snapshot: Snapshot) => Promise<void>, check?: () => Promise<void>, telemetryUserId: string | null = null) {
  let snapshot = root.relationshipEngine!;
  for (const turn of snapshot.pending) {
    const history = root.history as any[];
    if (!history?.some(t => t.requestId === turn.requestId && t.role === "user" && t.text === turn.message) ||
      !history.some(t => t.requestId === turn.requestId && t.role === "misaki" && t.text === turn.reply)) throw new Error("temporary_canonical_turn_required");
    // Pending turn remains encrypted/durable if validation or analysis fails.
    for (const type of criticalCandidates(turn.message)) {
      const events = snapshot.criticalEvents ?? [];
      if (events.some(e => e.request_id === turn.requestId && e.event_type === type)) continue;
      await check?.();
      const confirmed = await validateCriticalEvent(turn, type, events, createGeminiTelemetrySink("critical_validator", telemetryUserId, turn.requestId));
      await check?.();
      if (confirmed) {
        snapshot = { ...snapshot, state: { ...snapshot.state,
          relationshipStatus: type === "romantic_acceptance" ? "romantic_partner" : type === "relationship_end" ? "none" : snapshot.state.relationshipStatus },
          version: snapshot.version + 1, criticalEvents: [...events, { request_id: turn.requestId, event_type: type }] };
      }
    }
    await check?.();
    const evidence = await analyzeRelationshipEvidence(turn, createGeminiTelemetrySink("relationship_analyzer", telemetryUserId, turn.requestId));
    await check?.();
    snapshot = applyTemporaryEvidence(snapshot, turn, evidence);
    if (save) await save(snapshot);
  }
  return snapshot;
}

async function runAnonymous(userId: string) {
  let root = await loadTemporaryRoot(userId, null);
  if (!root.relationshipEngine) return;
  await analyzeTemporarySnapshot(root, async snapshot => {
    await editTemporaryRoot(userId, { ...root, relationshipEngine: snapshot }, "relationship-analysis");
    root = await loadTemporaryRoot(userId, null);
  }, undefined, userId);
}

async function runPermanent(userId: string) {
  // Import and ordinary processing share the claimed per-user lease.
  const store = new CanonicalRelationshipStore(createServerSupabase());
  // Scan saved canonical turns chronologically; one failed predecessor stops later application.
  const turns = await store.rows("misaki_relationship_events", userId, q => q.eq("event_type", "chat_turn_completed").order("id", { ascending: true }));
  const ledgers = await store.rows("misaki_relationship_processing", userId, q => q.eq("processing_version", PROCESSING_VERSION));
  // Do not analyze pre-cutover history with a new model/version.
  const boundary = process.env.MISAKI_RELATIONSHIP_ENGINE_START_AT;
  if (!boundary || !Number.isFinite(Date.parse(boundary))) throw new Error("relationship_start_boundary_required");
  let count = 0;
  for (const turn of turns) {
    if (Date.parse(turn.created_at) < Date.parse(boundary)) continue;
    if (ledgers.some(l => l.request_id === turn.request_id && l.status === "applied")) continue;
    if (++count > 3) break;
    const result = await processRelationshipTurn(store, userId, turn.request_id,
      t => analyzeRelationshipEvidence(t, createGeminiTelemetrySink("relationship_analyzer", userId, t.requestId)),
      (t, type, events) => validateCriticalEvent(t, type, events, createGeminiTelemetrySink("critical_validator", userId, t.requestId)),
      (check, token) => importPermanentRelationship(userId, turn.request_id, token, check));
    if (result.status === "deferred") break;
  }
}

/** Called via Next after(): never changes an already-successful chat/quota receipt. */
export async function resumeRelationshipProcessing(userId: string, anonymous: boolean) {
  if (!engineEnabled()) return;
  const key = `${userId}:${anonymous}`;
  if (running.has(key)) return running.get(key);
  const task = (anonymous ? runAnonymous(userId) : runPermanent(userId))
    .catch(() => { console.error("RELATIONSHIP V1 PROCESSING RETRY REQUIRED"); })
    .finally(() => running.delete(key));
  running.set(key, task);
  return task;
}

export async function importPermanentRelationship(userId: string, requestId: string, token: string, check: () => Promise<void>) {
  if (!engineEnabled()) return;
  await check();
  const db = createServerSupabase();
  const { data: imported, error: importError } = await db.from("misaki_relationship_temporary_v1_imports").select("user_id").eq("user_id", userId).maybeSingle();
  if (importError) throw new Error("relationship_import_read_failed");
  if (imported) return;
  const { data: root, error } = await db.from("misaki_temporary_roots").select("token,revision,expires_at").eq("user_id", userId).maybeSingle();
  if (error) throw new Error("relationship_import_root_read_failed");
  if (!root) return;
  // An expired anonymous checkpoint is no longer importable and must not poison
  // permanent Relationship processing. Invalid/unverifiable live roots still fail closed.
  if (Date.parse(root.expires_at) <= Date.now()) return;
  const verified = openTemporaryState(root.token);
  if (!verified) throw new Error("relationship_import_root_invalid");
  let snapshot = verified.state.relationshipEngine;
  if (!snapshot) return;
  // Once auth is permanent the temporary writer rejects writes. Finish the frozen
  // verified trajectory in memory and materialize atomically through the import RPC.
  if (snapshot.pending.length) snapshot = await analyzeTemporarySnapshot(verified.state, undefined, check, userId);
  await check();
  const { error: rpcError } = await db.rpc("import_misaki_temporary_relationship_v2", { p_user_id: userId, p_request_id: requestId, p_processing_version: PROCESSING_VERSION, p_lease_token: token, p_source_revision: root.revision,
    ...Object.fromEntries(AXES.map(axis => [`p_${axis}`, snapshot.state[axis]])), p_relationship_status: snapshot.state.relationshipStatus ?? "none",
    p_engine_version: PROCESSING_VERSION, p_payload: snapshot });
  if (rpcError) throw new Error(`relationship_import_failed:${rpcError.code ?? ""}:${rpcError.message ?? ""}`);
}

export function pendingRelationshipGuide(root: RootState) {
  return root.relationshipCriticalPending || root.relationshipEngine?.pending.some(t => criticalCandidates(t.message).length)
    ? "【未解決の明示的関係イベント】直近の関係変更は検証待ち。成立・継続・復縁を断定せず、現在のユーザーの境界を優先してください。" : "";
}

import type { RelationshipTimeContext } from "./relationship-time";
import type { RelationshipSignalAssessment } from "./relationship-signal";
import { reduceRelationshipEmotion, type RelationshipPatternContext } from "./relationship-emotion-reducer";
import { createActionDecisionGuide, reduceRelationshipAction, type ActionDecision } from "./relationship-action-reducer";
import type { RelationshipStoryState } from "./relationship-patterns";

export function previewRelationshipTurn(context: RelationshipTimeContext | null, signals: RelationshipSignalAssessment, patterns?: RelationshipPatternContext) {
  const allowed = new Set(["neutral","happy","affectionate","concerned","hurt","sulky","guarded"]);
  const primary = allowed.has(context?.emotionPrimary ?? "") ? context!.emotionPrimary as any : "neutral";
  const emotion = reduceRelationshipEmotion({previous:{primary,intensity:context?.emotionIntensity ?? 0},signals,elapsedHours:context?.elapsedHours ?? 0,intimacyLevel:context?.intimacyLevel ?? "initial",patterns});
  const action = reduceRelationshipAction({previousAction:context?.actionState ?? "NORMAL",emotion,signals,intimacyLevel:context?.intimacyLevel ?? "initial",patterns});
  return {emotion,action};
}

export function createCurrentTurnActionGuide(decision: ActionDecision, afterglow: string = "none", secondary: string | null = null, story?: RelationshipStoryState) {
  const afterglowGuide: Record<string,string>={warm:"さっきまでの嬉しさが少し残っている。理由なく急に無機質へ戻らない。",tender:"やわらかな親愛や仲直り後の繊細さが残っている。甘さを盛りすぎず、少し丁寧に近づく。",repairing:"まだ完全には解けていないが、関係を戻したい気持ちもある。傷を蒸し返さず、即リセットもしない。",wary:"少し警戒が残っている。冷酷にはならず、距離を急に縮めない。",concerned:"気がかりが残っている。根拠のある範囲だけ気遣い、心配を捏造しない。",none:"余韻による追加調整はない。"};
  const decisionGuide: Record<string,string> = {
    affection_remains_but_hurt_still_needs_space: "好意は残っていても今は傷を優先する。短め・静かめでもよいが、別れや嫌悪を勝手に示さない。",
    affection_remains_while_hurt_softens: "傷は和らぎ始めている。いきなり元通りにせず、小さく応じる・少し柔らかくする程度から近づく。",
    care_and_warmth_coexist_with_grounded_concern: "心配を中心にしつつ、普段の親しさを消さない。尋問のように質問を重ねず、短く自然に気遣う。",
    concern_afterglow_still_invites_gentle_check_in: "心配だから気遣うが、直前まで傷・警戒・距離が残っていたなら、それまで消えたような満面の優しさにはしない。短く、少し素っ気なさやぎこちなさが残ってもよい。",
