import type {
  ProactiveDecisionContext,
  ProactiveDirection,
  ProactiveExpressionTag,
  RelationshipAction,
  RelationshipEmotion,
} from "./proactive-decision.ts";

export type MisakiPhotoTime = "morning" | "day" | "evening" | "night" | "any";

export type MisakiPhoto = {
  id: string;
  src: string;
  times: MisakiPhotoTime[];
  tags: ProactiveExpressionTag[];
  directions: ProactiveDirection[];
  actions: RelationshipAction[];
  emotions: RelationshipEmotion[];
  minRelationshipPoints: number;
  weight: number;
};

export type SelectMisakiPhotoInput = {
  currentTime: string;
  reply: string;
  decision: ProactiveDecisionContext;
  recentPhotoIds?: string[];
};

const PHOTO_ATTACH_RATE = 0.34;
const ALL_DIRECTIONS: ProactiveDirection[] = ["MISAKI", "USER", "US", "MISAKI_TO_USER", "MISAKI_TO_US"];
const ALL_ACTIONS: RelationshipAction[] = ["NORMAL", "WAIT", "TEASE", "SULK", "CHASE", "PULL", "RECONNECT"];
const ALL_EMOTIONS: RelationshipEmotion[] = ["neutral", "happy", "lonely", "sulky", "concerned", "affectionate"];

const PHOTOS: MisakiPhoto[] = [
  {
    id: "morning-01",
    src: "/misaki-morning.webp",
    times: ["morning"],
    tags: ["soft", "cheerful", "casual", "check_in"],
    directions: ALL_DIRECTIONS,
    actions: ALL_ACTIONS,
    emotions: ALL_EMOTIONS,
    minRelationshipPoints: 0,
    weight: 5,
  },
  {
    id: "day-01",
    src: "/misaki-day-intro.webp",
    times: ["day"],
    tags: ["cheerful", "casual", "soft", "playful", "encouraging", "check_in"],
    directions: ALL_DIRECTIONS,
    actions: ALL_ACTIONS,
    emotions: ALL_EMOTIONS,
    minRelationshipPoints: 0,
    weight: 5,
  },
  {
    id: "evening-01",
    src: "/misaki-evening.webp",
    times: ["evening"],
    tags: ["calm", "soft", "romantic", "affectionate", "miss_you"],
    directions: ALL_DIRECTIONS,
    actions: ALL_ACTIONS,
    emotions: ALL_EMOTIONS,
    minRelationshipPoints: 10,
    weight: 5,
  },
  {
    id: "night-01",
    src: "/misaki-night.webp",
    times: ["night"],
    tags: ["calm", "romantic", "sleepy", "soft", "affectionate", "miss_you"],
    directions: ALL_DIRECTIONS,
    actions: ALL_ACTIONS,
    emotions: ALL_EMOTIONS,
    minRelationshipPoints: 20,
    weight: 5,
  },
];

function hashText(text: string) {
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function getTimeBucket(currentTime: string): Exclude<MisakiPhotoTime, "any"> {
  const match = currentTime.match(/(\d{1,2}):(\d{2})/);
  const hour = Math.max(0, Math.min(23, Number(match?.[1] ?? 18)));
  if (hour >= 5 && hour < 10) return "morning";
  if (hour >= 10 && hour < 17) return "day";
  if (hour >= 17 && hour < 21) return "evening";
  return "night";
}

function scorePhoto(photo: MisakiPhoto, tags: ProactiveExpressionTag[]) {
  return tags.reduce(
    (score, tag) => score + (photo.tags.includes(tag) ? 3 : 0),
    0
  );
}

function weightedPick(photos: MisakiPhoto[], seed: number): MisakiPhoto | null {
  if (!photos.length) return null;
  const total = photos.reduce((sum, photo) => sum + Math.max(1, photo.weight), 0);
  let target = seed % total;
  for (const photo of photos) {
    const weight = Math.max(1, photo.weight);
    if (target < weight) return photo;
    target -= weight;
  }
  return photos[0] ?? null;
}

export function selectMisakiProactivePhoto(input: SelectMisakiPhotoInput): MisakiPhoto | null {
  const { currentTime, reply, decision, recentPhotoIds = [] } = input;
  if (!decision.shouldSend || !reply.trim()) return null;

  const seed = hashText(
    `${currentTime}|${decision.direction}|${decision.action}|${decision.emotion}|${decision.relationshipPoints}|${decision.tags.join(",")}|${reply}`
  );

  if (seed % 10000 >= Math.floor(PHOTO_ATTACH_RATE * 10000)) return null;

  const timeBucket = getTimeBucket(currentTime);
  let candidates = PHOTOS.filter((photo) =>
    decision.relationshipPoints >= photo.minRelationshipPoints &&
    (photo.times.includes(timeBucket) || photo.times.includes("any")) &&
    photo.directions.includes(decision.direction) &&
    photo.actions.includes(decision.action) &&
    photo.emotions.includes(decision.emotion)
  );

  if (!candidates.length) return null;

  const scored = candidates.map((photo) => ({
    photo,
    score: scorePhoto(photo, decision.tags),
  }));
  const bestScore = Math.max(...scored.map((item) => item.score));

  if (bestScore > 0) {
    candidates = scored
      .filter((item) => item.score === bestScore)
      .map((item) => item.photo);
  }

  const withoutRecent = candidates.filter((photo) => !recentPhotoIds.includes(photo.id));
  if (withoutRecent.length) candidates = withoutRecent;

  return weightedPick(
    candidates,
    hashText(`${seed}|${decision.tags.join("|")}|${timeBucket}|${decision.direction}`)
  );
}

export function getMisakiPhotoCatalog() {
  return PHOTOS;
}

-- Cron authenticates with a dedicated encrypted Vault secret, never a literal key.
create schema if not exists private;
do $$
begin
  if not exists (select 1 from vault.secrets where name='misaki_body_clock_cron') then
    perform vault.create_secret(encode(extensions.gen_random_bytes(32),'hex'),'misaki_body_clock_cron');
  end if;
end $$;
create or replace function private.verify_misaki_body_clock_secret(p_secret text)
returns boolean language sql security definer set search_path = ''
as $$
 select coalesce(length(p_secret)=64 and exists (
   select 1 from vault.decrypted_secrets
   where name='misaki_body_clock_cron'
     and extensions.digest(decrypted_secret,'sha256')=extensions.digest(p_secret,'sha256')
 ),false);
$$;
revoke all on function private.verify_misaki_body_clock_secret(text) from public, anon, authenticated;
grant usage on schema private to service_role;
grant execute on function private.verify_misaki_body_clock_secret(text) to service_role;
create or replace function public.verify_misaki_body_clock_secret(p_secret text)
returns boolean language sql security invoker set search_path = ''
as $$ select private.verify_misaki_body_clock_secret(p_secret); $$;
revoke all on function public.verify_misaki_body_clock_secret(text) from public, anon, authenticated;
grant execute on function public.verify_misaki_body_clock_secret(text) to service_role;

-- One transaction makes a delivery, its conversation history, and its daily count agree.
create or replace function public.finish_misaki_body_clock_delivery(
 p_user_id uuid, p_lease_until timestamptz, p_message text,
 p_photo_id text, p_photo_src text, p_photo_context jsonb, p_delay_minutes integer
) returns jsonb language plpgsql security invoker set search_path = ''
as $$
declare
 s public.background_push_state%rowtype;
 v_now timestamptz := clock_timestamp();
 v_today date := (clock_timestamp() at time zone 'Asia/Tokyo')::date;
 v_count integer;
 v_id uuid;
 v_next timestamptz;
 v_history jsonb;
begin
 select * into s from public.background_push_state where user_id=p_user_id for update;
 if not found or s.next_push_at is distinct from p_lease_until or p_lease_until <= v_now then
   raise exception 'body_clock_lease_expired';
 end if;
 v_count := case when s.push_date=v_today then greatest(coalesce(s.pushes_today,0),0) else 0 end;
 if v_count >= 4 then raise exception 'body_clock_daily_limit'; end if;
 if nullif(btrim(p_message),'') is null then raise exception 'body_clock_empty_message'; end if;
 v_next := v_now + make_interval(mins => greatest(45,least(210,p_delay_minutes)));
 insert into public.misaki_proactive_deliveries(user_id,message,photo_id,photo_src,photo_context,status,delivered_at)
 values(p_user_id,p_message,p_photo_id,p_photo_src,coalesce(p_photo_context,'{}'::jsonb),'delivered',v_now)
 returning id into v_id;
 insert into public.misaki_user_conversation_state(user_id) values(p_user_id) on conflict(user_id) do nothing;
 select history into v_history from public.misaki_user_conversation_state where user_id=p_user_id for update;
 if jsonb_typeof(v_history) is distinct from 'array' then v_history := '[]'::jsonb; end if;
 v_history := v_history || jsonb_build_array(jsonb_build_object('role','misaki','text',p_message,'sentAt',v_now));
 select coalesce(jsonb_agg(value order by ord),'[]'::jsonb) into v_history
 from jsonb_array_elements(v_history) with ordinality e(value,ord)
 where ord > greatest(0,jsonb_array_length(v_history)-60);
 update public.misaki_user_conversation_state
 set history=v_history, message_count=greatest(coalesce(message_count,0),0)+1, updated_at=v_now
 where user_id=p_user_id;
 update public.background_push_state set last_push_at=v_now,next_push_at=v_next,
 push_date=v_today,pushes_today=v_count+1,last_background_message=p_message,updated_at=v_now
