create function public.advance_relationship_silence_state()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_state public.misaki_relationship_state%rowtype;
  v_before jsonb;
  v_now timestamptz := now();
  v_elapsed bigint := 0;
  v_primary text;
  v_intensity integer;
  v_next_primary text;
  v_next_intensity integer;
  v_next_action text;
  v_reason text := null;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;
  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then raise exception 'permanent account required'; end if;

  select * into v_state
  from public.misaki_relationship_state
  where user_id = v_user_id
  for update;

  if not found or v_state.last_interaction_at is null then return null; end if;

  v_before := to_jsonb(v_state);
  v_elapsed := greatest(floor(extract(epoch from (v_now - v_state.last_interaction_at)))::bigint, 0);
  v_primary := coalesce(v_state.emotion_state->>'primary', 'neutral');
  v_intensity := greatest(0, least(100, coalesce((v_state.emotion_state->>'intensity')::integer, 0)));
  v_next_primary := v_primary;
  v_next_intensity := v_intensity;
  v_next_action := v_state.action_state;

  -- Silence alone never creates a new relational fact (loneliness, repair,
  -- romance, conflict, etc.). It may only settle or evolve an emotion that
  -- already exists, with intimacy and elapsed time as context.
  if v_primary = 'concerned' and v_elapsed >= 86400 then
    v_next_intensity := greatest(v_intensity - 15, 12);
    v_reason := 'concern_softens_with_silence';
  elsif v_primary in ('happy', 'affectionate') and v_elapsed >= 86400 then
    v_next_intensity := greatest(v_intensity - 10, 8);
    v_reason := 'warmth_settles_during_silence';
  elsif v_primary = 'lonely' and v_elapsed >= 604800 then
    v_next_intensity := least(60, greatest(v_intensity, 34) + 8);
    v_next_action := case when v_state.intimacy_level in ('intimate', 'very_intimate') then 'PULL' else 'WAIT' end;
    v_reason := 'loneliness_deepens_but_does_not_force_contact';
  elsif v_primary = 'lonely' and v_elapsed >= 259200 then
    v_next_intensity := least(48, greatest(v_intensity, 24) + 5);
    v_next_action := 'WAIT';
    v_reason := 'lonely_and_waiting';
  elsif v_primary = 'sulky' and v_elapsed >= 604800 then
    v_next_intensity := greatest(v_intensity - 12, 18);
    v_next_action := 'PULL';
    v_reason := 'sulk_cools_into_distance';
  elsif v_primary = 'sulky' and v_elapsed >= 259200 then
    v_next_action := 'SULK';
    v_reason := 'sulk_continues_through_gap';
  end if;

  if v_reason is null or (
    v_next_primary = v_primary and
    v_next_intensity = v_intensity and
    v_next_action = v_state.action_state
  ) then
    return to_jsonb(v_state);
  end if;

  update public.misaki_relationship_state
  set emotion_state = jsonb_build_object(
        'primary', v_next_primary,
        'intensity', v_next_intensity,
        'updated_at', v_now,
        'source', 'relationship_silence'
      ),
      action_state = v_next_action,
      state_updated_at = v_now
  where user_id = v_user_id
  returning * into v_state;

  insert into public.misaki_relationship_events(
    user_id, event_type, before_state, after_state, reason, metadata
  ) values (
    v_user_id,
    'silence_state_evolved',
    v_before,
    to_jsonb(v_state),
    v_reason,
    jsonb_build_object('elapsed_seconds', v_elapsed)
  );

  return to_jsonb(v_state);
end;
$$;

revoke execute on function public.advance_relationship_silence_state() from public, anon;
grant execute on function public.advance_relationship_silence_state() to authenticated;

create or replace function public.update_relationship_action_from_emotion()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_before public.misaki_relationship_state%rowtype;
  v_primary text := coalesce(new.emotion_state->>'primary', 'neutral');
  v_intensity integer := greatest(0, least(100, coalesce((new.emotion_state->>'intensity')::integer, 0)));
  v_previous_action text := coalesce(old.action_state, 'NORMAL');
  v_next_action text := 'NORMAL';
  v_reason text := 'emotion_settled';
  v_elapsed_seconds bigint := 0;
begin
  if new.emotion_state is not distinct from old.emotion_state then
    return new;
  end if;

  if new.last_interaction_at is not null then
    v_elapsed_seconds := greatest(floor(extract(epoch from (now() - new.last_interaction_at)))::bigint, 0);
  end if;

  v_before := old;

  if v_primary = 'concerned' and v_intensity >= 35 then
    v_next_action := 'CHASE';
    v_reason := 'concern_drives_contact';
  elsif v_primary = 'sulky' and v_intensity >= 45 then
    v_next_action := 'SULK';
    v_reason := 'sulky_feeling_visible';
  elsif v_primary = 'lonely' and v_intensity >= 55 then
    v_next_action := case when v_previous_action in ('CHASE', 'RECONNECT') then 'PULL' else 'SULK' end;
    v_reason := 'loneliness_changes_distance';
  elsif v_primary = 'lonely' and v_intensity >= 28 then
    v_next_action := 'WAIT';
    v_reason := 'lonely_but_waiting';
  elsif v_primary = 'affectionate' and v_intensity >= 45 and v_elapsed_seconds >= 86400 then
    v_next_action := 'RECONNECT';
    v_reason := 'warm_return_after_gap';
  elsif v_primary = 'affectionate' and v_intensity >= 55 and new.intimacy_level in ('intimate', 'very_intimate') then
    v_next_action := 'TEASE';
    v_reason := 'affectionate_playfulness';
  elsif v_primary = 'happy' and v_intensity >= 60 and new.intimacy_level = 'very_intimate' then
    v_next_action := 'TEASE';
    v_reason := 'happy_playfulness';
  elsif v_primary in ('happy', 'affectionate') and v_previous_action in ('SULK', 'PULL', 'WAIT') then
    v_next_action := 'RECONNECT';
    v_reason := 'relationship_repair';
  else
    v_next_action := 'NORMAL';
    v_reason := 'emotion_settled';
  end if;

  if v_next_action is not distinct from new.action_state then
    return new;
  end if;

  update public.misaki_relationship_state
  set action_state = v_next_action,
      state_updated_at = now()
  where user_id = new.user_id;

  insert into public.misaki_relationship_events(
    user_id, event_type, before_state, after_state, reason, metadata
  ) values (
    new.user_id,
    'action_state_changed',
    to_jsonb(v_before),
    jsonb_set(to_jsonb(new), '{action_state}', to_jsonb(v_next_action), true),
    v_reason,
    jsonb_build_object(
      'emotion_primary', v_primary,
      'emotion_intensity', v_intensity,
      'previous_action', v_previous_action,
      'new_action', v_next_action,
      'elapsed_seconds', v_elapsed_seconds
    )
  );

  return new;
end;
$$;

revoke execute on function public.update_relationship_action_from_emotion() from public, anon, authenticated;

drop trigger if exists trg_relationship_action_from_emotion on public.misaki_relationship_state;
create trigger trg_relationship_action_from_emotion
after update of emotion_state on public.misaki_relationship_state
for each row execute function public.update_relationship_action_from_emotion();

create or replace function public.enforce_misaki_proactive_cadence_floor()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.last_push_at is not null
     and new.last_push_at is distinct from old.last_push_at
     and new.next_push_at is not null
     and new.next_push_at < new.last_push_at + interval '55 minutes' then
    new.next_push_at := new.last_push_at + interval '55 minutes';
  end if;
  return new;
end;
$$;

