create or replace function public.consume_proactive_message()
returns table(allowed boolean, message_count integer, remaining integer, retry_after_seconds integer)
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_today date := (v_now at time zone 'Asia/Tokyo')::date;
  v_count integer := 0;
  v_last_sent timestamptz;
  v_retry integer := 0;
begin
  if v_user_id is null then raise exception 'Authentication required'; end if;
  if coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then raise exception 'Permanent account required'; end if;

  insert into public.proactive_message_usage(user_id,usage_date,message_count,last_sent_at,updated_at)
  values(v_user_id,v_today,0,null,v_now)
  on conflict (user_id,usage_date) do nothing;

  select p.message_count,p.last_sent_at into v_count,v_last_sent
  from public.proactive_message_usage p
  where p.user_id=v_user_id and p.usage_date=v_today
  for update;

  if v_count >= 4 then return query select false,v_count,0,0; return; end if;

  if v_last_sent is not null and v_last_sent + interval '55 minutes' > v_now then
    v_retry := greatest(ceil(extract(epoch from ((v_last_sent + interval '55 minutes') - v_now)))::integer,1);
    return query select false,v_count,greatest(4-v_count,0),v_retry; return;
  end if;

  update public.proactive_message_usage p
  set message_count=p.message_count+1,last_sent_at=v_now,updated_at=v_now
  where p.user_id=v_user_id and p.usage_date=v_today
  returning p.message_count into v_count;

  return query select true,v_count,greatest(4-v_count,0),0;
end;
$function$;

revoke execute on function public.consume_proactive_message() from public, anon;
grant execute on function public.consume_proactive_message() to authenticated;

-- Explicit email-save checkpoint. A snapshot replaces itself; it is never a delta.
-- SECURITY DEFINER is necessary because the conversation table has no direct
-- client insert/update policies. Ownership and anonymous status are checked here.
create or replace function public.save_anonymous_conversation_state(p_history jsonb, p_memory jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_history jsonb;
  v_memory jsonb;
begin
  if v_user_id is null then raise exception 'anonymous account required'; end if;
  -- Serialize snapshots and hold anonymous status stable against confirmation.
  perform 1 from auth.users where id = v_user_id and is_anonymous = true for update;
  if not found then
    raise exception 'anonymous account required';
  end if;
  if jsonb_typeof(p_history) is distinct from 'array' or jsonb_typeof(p_memory) is distinct from 'array' then
    raise exception 'invalid snapshot';
  end if;
  select coalesce(jsonb_agg(item order by ord), '[]'::jsonb) into v_history
  from (
    select jsonb_build_object('role', elem->>'role', 'text', left(btrim(elem->>'text'), 2000),
      'sentAt', to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) as item, ord
    from jsonb_array_elements(p_history) with ordinality a(elem, ord)
    where elem->>'role' in ('user', 'misaki') and jsonb_typeof(elem->'text') = 'string'
      and length(btrim(elem->>'text')) > 0
    order by ord desc limit 60
  ) items;
  select coalesce(jsonb_agg(item order by ord), '[]'::jsonb) into v_memory
  from (
    select to_jsonb(left(btrim(elem #>> '{}'), 500)) as item, ord
    from jsonb_array_elements(p_memory) with ordinality a(elem, ord)
    where jsonb_typeof(elem) = 'string' and length(btrim(elem #>> '{}')) > 0
    order by ord desc limit 30
  ) items;

  insert into public.misaki_user_conversation_state(user_id, history, memory, updated_at)
  values (v_user_id, v_history, v_memory, now())
  on conflict (user_id) do update set history = excluded.history, memory = excluded.memory, updated_at = now()
  where jsonb_array_length(misaki_user_conversation_state.history) <= jsonb_array_length(excluded.history);
  return jsonb_build_object('saved', true);
end;
$$;
revoke all on function public.save_anonymous_conversation_state(jsonb,jsonb) from public, anon;
grant execute on function public.save_anonymous_conversation_state(jsonb,jsonb) to authenticated;

create or replace function public.sync_user_conversation_state(
  p_history jsonb,
  p_memory jsonb default null::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_existing_history jsonb := '[]'::jsonb;
  v_existing_memory jsonb := '[]'::jsonb;
  v_incoming_history jsonb := '[]'::jsonb;
  v_incoming_memory jsonb := null;
  v_merged_history jsonb := '[]'::jsonb;
  v_final_memory jsonb := '[]'::jsonb;
  v_overlap int := 0;
  v_server_len int := 0;
  v_incoming_len int := 0;
  v_is_delta boolean := false;
  i int;
  j int;
begin
  if v_user_id is null then raise exception 'not authenticated'; end if;

  select coalesce(history,'[]'::jsonb), coalesce(memory,'[]'::jsonb)
    into v_existing_history, v_existing_memory
  from public.misaki_user_conversation_state
  where user_id = v_user_id;

  if not found then
    v_existing_history := '[]'::jsonb;
    v_existing_memory := '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'role', x.role,
      'text', x.text,
      'sentAt', coalesce(x.sent_at, to_char(clock_timestamp(), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
    ) order by x.ord
  ), '[]'::jsonb)
  into v_incoming_history
  from (
    select ord,
           elem->>'role' as role,
           btrim(elem->>'text') as text,
           nullif(elem->>'sentAt','') as sent_at
    from jsonb_array_elements(coalesce(p_history,'[]'::jsonb)) with ordinality a(elem,ord)
    where elem->>'role' in ('user','misaki')
      and length(btrim(coalesce(elem->>'text',''))) > 0
  ) x;

  v_server_len := jsonb_array_length(v_existing_history);
  v_incoming_len := jsonb_array_length(v_incoming_history);
  v_is_delta := v_incoming_len = 2
    and v_incoming_history->0->>'role' = 'user'
    and v_incoming_history->1->>'role' = 'misaki';

  for i in reverse least(v_server_len, v_incoming_len)..1 loop
    j := 0;
    while j < i loop
      exit when coalesce(v_existing_history->(v_server_len-i+j)->>'role','') <> coalesce(v_incoming_history->j->>'role','')
             or coalesce(v_existing_history->(v_server_len-i+j)->>'text','') <> coalesce(v_incoming_history->j->>'text','');
      j := j + 1;
    end loop;
    if j = i then v_overlap := i; exit; end if;
  end loop;

  if v_server_len = 0 then
    v_merged_history := v_incoming_history;
  elsif v_is_delta then
    if v_overlap > 0 then
      v_merged_history := v_existing_history || (
        select coalesce(jsonb_agg(elem order by ord),'[]'::jsonb)
        from jsonb_array_elements(v_incoming_history) with ordinality t(elem,ord)
        where ord > v_overlap
      );
    else
      v_merged_history := v_existing_history || v_incoming_history;
    end if;
  elsif v_overlap > 0 then
    v_merged_history := v_existing_history || (
      select coalesce(jsonb_agg(elem order by ord),'[]'::jsonb)
      from jsonb_array_elements(v_incoming_history) with ordinality t(elem,ord)
      where ord > v_overlap
    );
  else
    v_merged_history := v_existing_history;
  end if;

  select coalesce(jsonb_agg(elem order by ord),'[]'::jsonb)
    into v_merged_history
  from jsonb_array_elements(v_merged_history) with ordinality t(elem,ord)
  where ord > greatest(jsonb_array_length(v_merged_history)-60,0);

  if p_memory is null then
    v_final_memory := v_existing_memory;
  else
    select coalesce(jsonb_agg(to_jsonb(val) order by ord),'[]'::jsonb)
      into v_incoming_memory
    from (
      select distinct on (btrim(value)) btrim(value) val, ord
      from jsonb_array_elements_text(coalesce(p_memory,'[]'::jsonb)) with ordinality t(value,ord)
      where length(btrim(value)) > 0
      order by btrim(value), ord
    ) q;
    v_final_memory := coalesce(v_incoming_memory,'[]'::jsonb);
  end if;

  insert into public.misaki_user_conversation_state(user_id,history,memory,updated_at)
  values(v_user_id,v_merged_history,v_final_memory,now())
  on conflict(user_id) do update set
    history=excluded.history,
    memory=excluded.memory,
    updated_at=now();

  return jsonb_build_object(
    'historyCount',jsonb_array_length(v_merged_history),
    'memoryCount',jsonb_array_length(v_final_memory),
    'overlapCount',v_overlap,
    'deltaMode',v_is_delta
  );
end;
$$;

-- Shared, encrypted, expiring anonymous transport root. Unlike immutable turn
-- receipts, this advances on chat, explicit edits and successful Body Clock delivery.
-- No anonymous plaintext permanent root exists until email saving is requested.
create table public.misaki_temporary_roots (
